{"content":"const fs = require('fs');

function main() {
  const filePath = process.argv[2];
  if (!filePath) {
    console.error('Usage: node parse_tx.js <path_to_hex_file>');
    process.exit(1);
  }

  let hexRaw;
  try {
    hexRaw = fs.readFileSync(filePath, 'utf8');
  } catch (e) {
    console.error(`Error reading file: ${e.message}`);
    process.exit(1);
  }

  const hex = hexRaw.replace(/\s+/g, '').toLowerCase();

  if (hex.length === 0) {
    console.error('Error: empty hex string');
    process.exit(1);
  }
  if (hex.length % 2 !== 0) {
    console.error('Error: hex string has odd length');
    process.exit(1);
  }
  if (!/^[0-9a-f]*$/.test(hex)) {
    console.error('Error: invalid hex string');
    process.exit(1);
  }

  let buf;
  try {
    buf = Buffer.from(hex, 'hex');
  } catch (e) {
    console.error(`Error: invalid hex string: ${e.message}`);
    process.exit(1);
  }

  let offset = 0;

  function need(n) {
    if (offset + n > buf.length) {
      console.error('Error: unexpected end of data (incomplete transaction)');
      process.exit(1);
    }
  }

  function readUInt32LE() {
    need(4);
    const v = buf.readUInt32LE(offset);
    offset += 4;
    return v;
  }

  function readUInt64() {
    need(8);
    const v = buf.readBigUInt64LE(offset);
    offset += 8;
    // Convert to Number; values in Bitcoin are well within safe integer range
    // (max supply 2.1e15 < 2^53). Preserve exactness check for huge values.
    if (v > BigInt(Number.MAX_SAFE_INTEGER)) {
      console.error('Error: value exceeds max safe integer');
      process.exit(1);
    }
    return Number(v);
  }

  function readVarInt() {
    need(1);
    const first = buf[offset];
    offset += 1;
    if (first < 0xfd) {
      return first;
    } else if (first === 0xfd) {
      need(2);
      const v = buf.readUInt16LE(offset);
      offset += 2;
      if (v < 0xfd) {
        console.error('Error: non-minimal VarInt encoding');
        process.exit(1);
      }
      return v;
    } else if (first === 0xfe) {
      need(4);
      const v = buf.readUInt32LE(offset);
      offset += 4;
      if (v <= 0xffff) {
        console.error('Error: non-minimal VarInt encoding');
        process.exit(1);
      }
      return v;
    } else {
      need(8);
      const v = buf.readBigUInt64LE(offset);
      offset += 8;
      if (v <= BigInt(0xffffffff)) {
        console.error('Error: non-minimal VarInt encoding');
        process.exit(1);
      }
      if (v > BigInt(Number.MAX_SAFE_INTEGER)) {
        console.error('Error: VarInt exceeds max safe integer');
        process.exit(1);
      }
      return Number(v);
    }
  }

  function readBytes(n) {
    need(n);
    const b = buf.slice(offset, offset + n);
    offset += n;
    return b;
  }

  // Version
  const version = readUInt32LE();

  // Inputs
  const inputCount = readVarInt();
  const inputs = [];
  for (let i = 0; i < inputCount; i++) {
    const txidBytes = readBytes(32);
    const txid = Buffer.from(txidBytes).reverse().toString('hex');
    const vout = readUInt32LE();
    const scriptsigLen = readVarInt();
    const scriptsigBytes = readBytes(scriptsigLen);
    const scriptsig = scriptsigBytes.toString('hex');
    const sequence = readUInt32LE();
    inputs.push({ txid, vout, scriptsig, sequence });
  }

  // Outputs
  const outputCount = readVarInt();
  const outputs = [];
  for (let i = 0; i < outputCount; i++) {
    const value = readUInt64();
    const scriptpubkeyLen = readVarInt();
    const scriptpubkeyBytes = readBytes(scriptpubkeyLen);
    const scriptpubkey = scriptpubkeyBytes.toString('hex');
    outputs.push({ value, scriptpubkey });
  }

  // Locktime
  const locktime = readUInt32LE();

  const result = {
    version,
    input_count: inputCount,
    inputs,
    output_count: outputCount,
    outputs,
    locktime,
  };

  process.stdout.write(JSON.stringify(result, null, 2) + '\n');
}

main();
